scripts.陆文龙.txt:
//和陆文龙对话

	If ($Event == 695) @Event695;
	If ($Event == 700) @Event700;
	
@Event695:	
	
	If ($Talkluwenlong == 0) @Talkluwenlong0;
	If ($Talkluwenlong == 1) @Talkluwenlong1;
	
@Talkluwenlong0:
	Say("陆文龙：原来是独孤大哥和张姐姐，文龙还没向两位道谢呢。", 97);
	Say("独孤剑：陆将军不必客气。对了，岳元帅呢？", 2);
	Say("陆文龙：元帅出营探察军情去了，云大哥在大帐内，有什么事可以去大帐。", 97);
	Assign($Talkluwenlong, 1);
	Return;
	
@Talkluwenlong1:
	Say("陆文龙：云大哥在大帐，独孤大哥可以去找他。", 97);
	Return;
	
	
@Event700:
	Say("陆文龙：我听云大哥说元帅有危险，我要同你们一起去救他！", 97);
	Say("独孤剑：我和张姑娘先去，你和岳云将军随后赶来吧！", 1);
	Say("陆文龙：好！", 97);
	Return;

scripts.牛皋对话.txt:
// 岳飞大营里与牛皋的对话

	If ($Event == 440) @Event440;
	If ($Event == 450) @Event440;
	If ($Event >= 695) @Event695;
				
	Say("牛皋：俺牛皋可是个粗人，有啥说啥，不会转弯。你们若是来找元帅打秋风，就找岳云拿几两银子了回去好生过活，就不要再去唠叨元帅了。", 0);
	Return;
	
@Event440:	
	Say("牛皋：小小陆文龙，何足挂齿！俺老牛要是再年轻十岁，还不几锏呼将过去三下五除二把那王八糕子打得稀里哗啦，还用的着元帅操心？", 0);
	Return;
	
@Event695:
	Say("牛皋：原来是独孤公子和张姑娘，好久不见啦，两位可好？", 0);
	Return;

scripts.宋兵对话1.txt:
// 和军营守卫对话

	If ($Event >= 440) @Event440;
	
	Say("卫兵：二位就在营中走走，阵前就不要去了，那里危险得很。", 0);
	Return;

@Event440:	
	Say("卫兵：两位请进吧！岳元帅吩咐过我们，独孤公子和张姑娘可以随意进出。", 0);
	Return;

scripts.宋兵对话2.txt:
// 和阵前守卫对话

	Say("营门守卫：前面是两军交战之地，很危险。请二位止步，还是留在营内比较安全！", 0);
	Return;

scripts.宋兵对话3.txt:
// 和宋兵的对话3
	
	If ($Event == 430) @Event430;
	If ($Event == 440) @Event440;
	If ($Event >> 660) @Event690;
	
@Event430:
	Say("兵士：这位大哥，瞧我们的吧。打到黄龙府，活捉金兀术……");
	Return;
	
@Event440:
	Say("兵士：姓陆的金狗还真凶……哼，要是云将军上阵，准把他打趴下！");
	Return;
	
@Event690:
	Say("兵士：陆将军可真厉害——云将军和他比试了三十五场，赢了十七场，输了十八场……不过这次云将军准赢！");
	Return;

scripts.宋兵对话4.txt:
// 和宋兵的对话4

	If ($Event >> 480) @Eventmore480;  //陆文龙归顺后
	
	Say("宋兵：我猜想，那陆文龙只怕是个汉人吧，金国人怎么生得出来这么厉害的一员猛将？", 0);
	Return;
	
@Eventmore480:
	Say("宋兵：我早就说过陆文龙将军不像是金国人，果然没有说错！");
	Return;

scripts.宋兵对话5.txt:
// 和宋兵的对话5

	If ($Event >> 480) @Eventmore480;  //陆文龙归顺后

	Say("宋兵：听说金兵中来了个陆文龙，是兀术的养子，武功甚是了得。", 0);
	Return;
	
@Eventmore480:
	Say("宋兵：现在陆文龙将军归顺了岳元帅，我们宋军又得了一员猛将，真是太好了！那金兀术估计要气得翘胡子啦，哈哈哈！");
	Return;

scripts.张琳心对话.txt:
// 与张琳心的对话

	If ($Event << 430) @Eventless430;
	If ($Event == 430) @Event430;			//两个军营都已去过
	If ($Event == 440) @Event440;
	If ($Event == 450) @Event450;
	If ($Event == 695) @Event695;
	If ($Event == 700) @Event700;
	
@Eventless430:	
	If ($Talkyueyun == 0) @Eventyueyun0;	//尚未见到岳云
	If ($Talkyueyun == 1) @Eventyueyun1;	//已经见到岳云
@Eventyueyun0:
	Say("独孤剑：岳家军威名远播，将士们个个意气风发，如果不是朝廷昏庸，估计早就把金人赶出中原了。", 1);
	Say("张琳心：我们去见岳元帅吧。", 21);
	Return;		
@Eventyueyun1:	
	Say("张琳心：我们去韩世忠大营吧。", 21);
	Return;	
	
@Event430:
	Say("张琳心：我们明天再来吧！", 21);
	Return;	
	
	
@Event440:
	Say("张琳心：我们去见岳飞元帅吧！", 21);
	Return;	
	
@Event450:
	Say("张琳心：岳元帅说凤凰山在大营的西边。", 21);
	Return;	
	
@Event695:
	Say("张琳心：独孤哥哥，我们快去见岳元帅吧。",21);
	Return;
	
@Event700:	
	Say("张琳心：独孤哥哥，我们赶快去凤凰山吧，晚了就来不及了！", 21);
	Return;

